   143	/// The cursor position and style.
   144	pub const Cursor = struct {
   145	    // The x/y position within the active area.
   146	    x: size.CellCountInt = 0,
   147	    y: size.CellCountInt = 0,
   148	
   149	    /// The visual style of the cursor. This defaults to block because
   150	    /// it has to default to something, but users of this struct are
   151	    /// encouraged to set their own default.
   152	    cursor_style: CursorStyle = .block,
   153	
   154	    /// The "last column flag (LCF)" as its called. If this is set then the
   155	    /// next character print will force a soft-wrap.
   156	    pending_wrap: bool = false,
   157	
   158	    /// The protected mode state of the cursor. If this is true then
   159	    /// all new characters printed will have the protected state set.
   160	    protected: bool = false,
   161	
   162	    /// The currently active style. This is the concrete style value
   163	    /// that should be kept up to date. The style ID to use for cell writing
   164	    /// is below.
   165	    style: style.Style = .{},
   166	
   167	    /// The currently active style ID. The style is page-specific so when
   168	    /// we change pages we need to ensure that we update that page with
   169	    /// our style when used.
   170	    style_id: style.Id = style.default_id,
   171	
   172	    /// The hyperlink ID that is currently active for the cursor. A value
   173	    /// of zero means no hyperlink is active. (Implements OSC8, saying that
   174	    /// so code search can find it.).
   175	    hyperlink_id: hyperlink.Id = 0,
   176	
   177	    /// This is the implicit ID to use for hyperlinks that don't specify
   178	    /// an ID. We do an overflowing add to this so repeats can technically
   179	    /// happen with carefully crafted inputs but for real workloads its
   180	    /// highly unlikely -- and the fix is for the TUI program to use explicit
   181	    /// IDs.
   182	    hyperlink_implicit_id: size.OffsetInt = 0,
   183	
   184	    /// Heap-allocated hyperlink state so that we can recreate it when
   185	    /// the cursor page pin changes. We can't get it from the old screen
   186	    /// state because the page may be cleared. This is heap allocated
   187	    /// because its most likely null.
   188	    hyperlink: ?*hyperlink.Hyperlink = null,
   189	
   190	    /// The current semantic content type for the cursor that will be
   191	    /// applied to any newly written cells.
   192	    semantic_content: pagepkg.Cell.SemanticContent = .output,
   193	    semantic_content_clear_eol: bool = false,
   194	
   195	    /// The pointers into the page list where the cursor is currently
   196	    /// located. This makes it faster to move the cursor.
   197	    page_pin: *PageList.Pin,
   198	    page_row: *pagepkg.Row,
   199	    page_cell: *pagepkg.Cell,
   200	
   201	    pub fn deinit(self: *Cursor, alloc: Allocator) void {
   202	        if (self.hyperlink) |link| {
   203	            link.deinit(alloc);
   204	            alloc.destroy(link);
   205	        }
   206	    }
   207	};
