1945	    /// Meta is everything that isn't the grid, such as styles, graphemes,
1946	    /// etc. `layout` places it directly after the grid.
1947	    pub const MetaLayout = struct {
1948	        /// The size of the block including internal alignment padding.
1949	        total_size: usize,
1950	        styles_start: usize,
1951	        styles_layout: StyleSet.Layout,
1952	        grapheme_alloc_start: usize,
1953	        grapheme_alloc_layout: GraphemeAlloc.Layout,
1954	        grapheme_map_start: usize,
1955	        grapheme_map_layout: GraphemeMap.Layout,
1956	        string_alloc_start: usize,
1957	        string_alloc_layout: StringAlloc.Layout,
1958	        hyperlink_set_start: usize,
1959	        hyperlink_set_layout: hyperlink.Set.Layout,
1960	        hyperlink_map_start: usize,
1961	        hyperlink_map_layout: hyperlink.Map.Layout,
1962	
1963	        /// The alignment of the block's start: the largest alignment any
1964	        /// member requires, so that the member offsets above don't depend
1965	        /// on where the block is placed.
1966	        pub const alignment = @max(
1967	            StyleSet.base_align.toByteUnits(),
1968	            GraphemeAlloc.base_align.toByteUnits(),
1969	            GraphemeMap.base_align.toByteUnits(),
1970	            StringAlloc.base_align.toByteUnits(),
1971	            hyperlink.Set.base_align.toByteUnits(),
1972	            hyperlink.Map.base_align.toByteUnits(),
1973	        );
1974	
1975	        /// Compute the layout of the block for the given capacity.
1976	        pub fn init(cap: Capacity) MetaLayout {
1977	            const styles_layout: StyleSet.Layout = .init(cap.styles);
1978	            const styles_start = 0;
1979	            const styles_end = styles_start + styles_layout.total_size;
1980	
1981	            const grapheme_alloc_layout = GraphemeAlloc.layout(cap.grapheme_bytes);
1982	            const grapheme_alloc_start = alignForward(usize, styles_end, GraphemeAlloc.base_align.toByteUnits());
1983	            const grapheme_alloc_end = grapheme_alloc_start + grapheme_alloc_layout.total_size;
1984	
1985	            const grapheme_count: usize = count: {
1986	                if (cap.grapheme_bytes == 0) break :count 0;
1987	                // Use divCeil to match GraphemeAlloc.layout() which uses alignForward,
1988	                // ensuring grapheme_map has capacity when grapheme_alloc has chunks.
1989	                const base = std.math.divCeil(usize, cap.grapheme_bytes, grapheme_chunk) catch unreachable;
1990	                break :count std.math.ceilPowerOfTwo(usize, base) catch unreachable;
1991	            };
1992	            const grapheme_map_layout = GraphemeMap.layout(@intCast(grapheme_count));
1993	            const grapheme_map_start = alignForward(usize, grapheme_alloc_end, GraphemeMap.base_align.toByteUnits());
1994	            const grapheme_map_end = grapheme_map_start + grapheme_map_layout.total_size;
1995	
1996	            const string_layout = StringAlloc.layout(cap.string_bytes);
1997	            const string_start = alignForward(usize, grapheme_map_end, StringAlloc.base_align.toByteUnits());
1998	            const string_end = string_start + string_layout.total_size;
1999	
2000	            // The set and the map are sized independently: the set
2001	            // from the number of unique hyperlinks, the map from the
2002	            // number of cells that have one. The map layout adds its
2003	            // load-factor headroom and rounds up to a power of two, so
2004	            // it always holds at least `hyperlink_cells` entries.
2005	            const hyperlink_count = @divFloor(cap.hyperlink_bytes, @sizeOf(hyperlink.Set.Item));
2006	            const hyperlink_set_layout: hyperlink.Set.Layout = .init(@intCast(hyperlink_count));
2007	            const hyperlink_set_start = alignForward(usize, string_end, hyperlink.Set.base_align.toByteUnits());
2008	            const hyperlink_set_end = hyperlink_set_start + hyperlink_set_layout.total_size;
2009	
2010	            const hyperlink_map_layout = hyperlink.Map.layout(cap.hyperlink_cells);
2011	            const hyperlink_map_start = alignForward(usize, hyperlink_set_end, hyperlink.Map.base_align.toByteUnits());
2012	            const hyperlink_map_end = hyperlink_map_start + hyperlink_map_layout.total_size;
2013	
2014	            return .{
2015	                .total_size = hyperlink_map_end,
2016	                .styles_start = styles_start,
2017	                .styles_layout = styles_layout,
2018	                .grapheme_alloc_start = grapheme_alloc_start,
2019	                .grapheme_alloc_layout = grapheme_alloc_layout,
2020	                .grapheme_map_start = grapheme_map_start,
2021	                .grapheme_map_layout = grapheme_map_layout,
2022	                .string_alloc_start = string_start,
2023	                .string_alloc_layout = string_layout,
2024	                .hyperlink_set_start = hyperlink_set_start,
2025	                .hyperlink_set_layout = hyperlink_set_layout,
2026	                .hyperlink_map_start = hyperlink_map_start,
2027	                .hyperlink_map_layout = hyperlink_map_layout,
2028	            };
2029	        }
2030	    };
