7749	            usize,
7750	            rows,
7751	            cap.rows,
7752	        ) catch {
7753	            // Not possible:
7754	            // - initialCapacity guarantees at least 1 row
7755	            // - numerator/denominator can't overflow because of comptime check above
7756	            unreachable;
7757	        };
7758	
7759	        // We always need at least one page extra so that we
7760	        // can fit partial pages to spread our active area across two pages.
7761	        // Even for caps that can't fit all rows in a single page, we add one
7762	        // because the most extra space we need at any given time is only
7763	        // the partial amount of one page.
7764	        const pages = pages_exact + 1;
7765	        assert(pages >= 2);
