5215	/// Temporary output memory used while creating a compressed page.
5216	///
5217	/// Standard-sized output borrows a page-pool item so repeated compression can
5218	/// reuse the same virtual mapping. Oversized pages use a temporary allocation
5219	/// from the page allocator and release it immediately after compression.
5220	///
5221	/// A borrowed item goes back to the pool through zero-mode decommit, which
5222	/// only has to clear the bytes the encoder wrote. Callers therefore pass the
5223	/// dirty length to `deinit` rather than paying to clear the whole item.
5224	const CompressionScratch = union(enum) {
5225	    pooled: *align(std.heap.page_size_min) [std_size]u8,
5226	    allocated: []align(std.heap.page_size_min) u8,
5227	
5228	    fn init(
5229	        pool: *MemoryPool,
5230	        required: usize,
5231	        raw_len: usize,
5232	    ) Allocator.Error!CompressionScratch {
5233	        assert(required <= raw_len);
5234	
5235	        if (required <= std_size) {
5716	
5717	        .heap => {
5718	            const page_alloc = pool.pages.allocator;
5719	            page_alloc.free(page.memory);
5720	        },
5721	    }
5722	
5723	    pool.nodes.destroy(node);
5724	}
