6346	/// Checks if a pin is valid for this pagelist. This is a very slow and
6347	/// expensive operation since we traverse the entire linked list in the
6348	/// worst case. Only for runtime safety/debug.
6349	pub fn pinIsValid(self: *const PageList, p: Pin) bool {
6350	    // This is very slow so we want to ensure we only ever
6351	    // call this during slow runtime safety builds.
6352	    comptime assert(build_options.slow_runtime_safety);
6353	
6354	    var it = self.pages.first;
6355	    while (it) |node| : (it = node.next) {
6356	        if (node != p.node) continue;
6357	        return p.y < node.rows() and
6358	            p.x < node.cols();
6359	    }
6360	
6361	    return false;
6362	}
