7734	    fn minMaxSize(cols: size.CellCountInt, rows: size.CellCountInt) usize {
7735	        // Invariant required to ensure our divCeil below cannot overflow.
7736	        comptime {
7737	            const max_rows = std.math.maxInt(size.CellCountInt);
7738	            _ = std.math.divCeil(usize, max_rows, 1) catch unreachable;
7739	        }
